<?php
require_once __DIR__.'/../includes/bootstrap.php';$errors=[];$identity='';$method='email';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$identity=trim((string)($_POST['identity']??''));if(!$errors){$q=db()->prepare('SELECT id,email,phone,full_name,email_verified_at FROM users WHERE LOWER(email)=LOWER(?) LIMIT 1');$q->execute([$identity]);$u=$q->fetch();if(!$u){$errors[]='No account was found for those details.';}elseif(empty($u['email_verified_at'])){$errors[]='That contact method has not been verified for this account. Choose the verified method.';}else{$code=(string)random_int(100000,999999);db()->prepare('DELETE FROM password_resets WHERE user_id=? OR expires_at<NOW()')->execute([$u['id']]);db()->prepare('INSERT INTO password_resets(user_id,method,code_hash,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL 10 MINUTE))')->execute([$u['id'],'email',password_hash($code,PASSWORD_DEFAULT)]);if(send_verification_code('email',$u['email'],$code,'CareBridge password reset')){$_SESSION['password_reset_user']=(int)$u['id'];$_SESSION['password_reset_method']='email';flash('success','A password reset code has been sent.');redirect('reset-password.php');}db()->prepare('DELETE FROM password_resets WHERE user_id=?')->execute([$u['id']]);$errors[]='Could not send the email. Please check the email configuration and try again.';}}}$pageTitle='Recover password';require __DIR__.'/../includes/header.php';?><section class="auth-layout"><div class="auth-aside"><span class="eyebrow">ACCOUNT RECOVERY</span><h1>Get back into CareBridge.</h1><p>We will send a one-time code to your registered email before allowing a password change.</p></div><div class="form-panel"><div class="form-heading"><h2>Forgot password?</h2><p>Enter the email address linked to your account.</p></div><?php if($errors):?><div class="alert alert-error"><ul><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><form method="post" class="stack-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Registered email<input type="email" name="identity" required value="<?=e($identity)?>" autocomplete="username"></label><button class="button button-full" type="submit">Send verification code →</button></form></div></section><?php require __DIR__.'/../includes/footer.php';?>